export const EMPTY_RPN_ROW = (): RpnRow => ({
  incidentName: '',
  causeDetail:  '',
  s: '',
  o: '',
  d: '',
  solution:     '',
});

export function mapDraftRpnRows(rows: MonthlyIncidentReportDraft['rpnRows']): RpnRow[] {
  if (!rows?.length) return [EMPTY_RPN_ROW()];
  return rows.map((r) => ({
    incidentName: r.incidentName ?? '',
    causeDetail:  r.causeDetail  ?? '',
    s: r.s ?? '',
    o: r.o ?? '',
    d: r.d ?? '',
    solution: r.solution ?? '',
  }));
}

export const isNativeMobile = () =>
  typeof navigator !== 'undefined' &&
  /android|iphone|ipad|ipod/i.test(navigator.userAgent);

export function fmtDate(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}

export function pct(count: number, total: number) {
  if (!total) return '0';
  return ((count / total) * 100).toFixed(1);
}

export function getRpnColor(rpn: number | null) {
  if (rpn === null) return '';
  return rpn >= 200 ? '#dc2626' : rpn >= 100 ? '#f59e0b' : '#10b981';
}

export function getPeriodLabel(filters: MedicalIncidentReportFilters): string {
  if (filters.dateFrom && filters.dateTo) {
    const from = new Date(filters.dateFrom);
    const to   = new Date(filters.dateTo);
    if (from.getFullYear() === to.getFullYear() && from.getMonth() === to.getMonth())
      return `Tháng ${from.getMonth() + 1}/${from.getFullYear()}`;
    return `${from.toLocaleDateString('vi-VN')} – ${to.toLocaleDateString('vi-VN')}`;
  }
  if (filters.year) return `Năm ${filters.year}`;
  return 'Kỳ báo cáo';
}

/** Title cột nhóm trên form Tab 4A / Mục 2 Hình 1 — `{index}. {title}`. */
export const INCIDENT_TYPE_GROUP_KEYS = [
  'group1', 'group2', 'group3', 'group4', 'group5', 'group6',
  'group7', 'group8', 'group9', 'group10', 'group11',
] as const;

export type IncidentTypeGroupKey = (typeof INCIDENT_TYPE_GROUP_KEYS)[number];

export const INCIDENT_TYPE_GROUP_TITLES: Record<IncidentTypeGroupKey, string> = {
  group1:  '1. Thực hiện quy trình kỹ thuật, thủ thuật chuyên môn',
  group2:  '2. Nhiễm khuẩn bệnh viện',
  group3:  '3. Thuốc và dịch truyền',
  group4:  '4. Máu và các chế phẩm máu',
  group5:  '5. Thiết bị y tế',
  group6:  '6. Hành vi',
  group7:  '7. Tai nạn đối với người bệnh',
  group8:  '8. Hạ tầng cơ sở',
  group9:  '9. Quản lý nguồn lực, tổ chức',
  group10: '10. Hồ sơ, tài liệu, thủ tục hành chính',
  group11: '11. Khác',
};

export function formTypeGroupKeys(item: IncidentReportSummaryItem): string[] {
  if (item.typeGroupKeys?.length) return item.typeGroupKeys;
  const keys: string[] = [];
  if (item.isClinical) keys.push('group1');
  if (item.isFall) keys.push('group7');
  return keys;
}

export function stripTypeGroupIndex(title: string): string {
  return title.replace(/^\d+\.\s*/, '');
}

export function typeGroupTitle(groupKey: string): string {
  const titled = INCIDENT_TYPE_GROUP_TITLES[groupKey as IncidentTypeGroupKey] ?? groupKey;
  return stripTypeGroupIndex(titled);
}

export function incidentCategoryCount(item: IncidentReportSummaryItem): number {
  if (item.typeGroupKeys?.length) return item.typeGroupKeys.length;
  return Number(!!item.isClinical) + Number(!!item.isService) + Number(!!item.isFall);
}

export function isMultiCategoryIncident(item: IncidentReportSummaryItem): boolean {
  return incidentCategoryCount(item) > 1;
}

export function filterSummaryByTypeGroup(
  items: IncidentReportSummaryItem[],
  groupKey: string,
): IncidentReportSummaryItem[] {
  return items.filter((item) => formTypeGroupKeys(item).includes(groupKey));
}

export function categoryChips(item: IncidentReportSummaryItem): string[] {
  return formTypeGroupKeys(item);
}

export type TypeGroupSummaryRow = {
  key: IncidentTypeGroupKey;
  title: string;
  count: number;
};

/** 11 hạng mục Hình 1; `visible` = ẩn count 0. Title không kèm số 1–11 (UI dùng dấu +). */
export function listTypeGroupSummaryRows(
  report: MedicalIncidentReport,
  opts?: { hideZero?: boolean },
): TypeGroupSummaryRow[] {
  const rows = INCIDENT_TYPE_GROUP_KEYS.map((key) => ({
    key,
    title: typeGroupTitle(key),
    count: report.byIncidentTypeGroup.find((x) => x.key === key)?.count ?? 0,
  }));
  return opts?.hideZero ? rows.filter((row) => row.count > 0) : rows;
}

/** Mục 1.2 stats — SSOT = cùng GET `/reports` với Mục 2. */
export function deriveMonthlySection1Stats(report: MedicalIncidentReport) {
  const voluntaryCount = report.byReportType.find((x) => x.key === 'voluntary')?.count ?? 0;
  const mandatoryCount = report.byReportType.find((x) => x.key === 'mandatory')?.count ?? 0;
  const reportingDepartments = report.byReportingDepartment.filter((d) => d.count > 0);
  const typeGroupRows = listTypeGroupSummaryRows(report, { hideZero: true });
  const typeGroupSum = listTypeGroupSummaryRows(report).reduce((sum, row) => sum + row.count, 0);

  return {
    voluntaryCount,
    mandatoryCount,
    reportingDepartments,
    typeGroupRows,
    typeGroupSum,
  };
}
