/**
 * Capture Chart.js canvas → base64 trước In / Preview / Word
 * (parity print · preview · docx).
 *
 * Match theo `data-chart-key` + optional Chart.js registry (ổn định hơn DOM
 * khi Mục 2 đang hidden / lần In đầu tiên).
 */
import type { ChartImages } from '../pages/MonthlyReportFormPage/components/PrintableRecommendationDoc';

export const ANALYSIS_SECTION_ID = 'monthly-report-section-analysis';

export const CHART_KEYS: (keyof ChartImages)[] = ['typeGroup', 'occurrence', 'causeGroup'];

type CaptureFn = () => string | null;

/** Live Chart.js instances — ưu tiên hơn canvas DOM khi first-print. */
const chartCaptureRegistry = new Map<string, CaptureFn>();

export function registerChartCapture(key: keyof ChartImages, fn: CaptureFn): () => void {
  chartCaptureRegistry.set(key, fn);
  return () => {
    if (chartCaptureRegistry.get(key) === fn) chartCaptureRegistry.delete(key);
  };
}

export function captureChartsFromRegistry(): ChartImages {
  const images: ChartImages = {};
  for (const key of CHART_KEYS) {
    const fn = chartCaptureRegistry.get(key);
    if (!fn) continue;
    try {
      const dataUrl = fn();
      if (dataUrl && dataUrl.startsWith('data:image') && dataUrl.length > 100) {
        images[key] = dataUrl;
      }
    } catch {
      // ignore
    }
  }
  return images;
}

function isUsableDataUrl(dataUrl: string | null | undefined): dataUrl is string {
  return !!dataUrl && dataUrl.startsWith('data:image') && dataUrl.length > 100;
}

export function captureChartsFromAnalysisSection(
  section: HTMLElement | null = document.getElementById(ANALYSIS_SECTION_ID),
): ChartImages {
  const images: ChartImages = {};
  if (!section) return images;

  for (const key of CHART_KEYS) {
    const wrap = section.querySelector(`[data-chart-key="${key}"]`);
    const canvas = wrap?.querySelector('canvas') ?? null;
    if (!canvas) continue;
    try {
      if (canvas.width < 8 || canvas.height < 8) continue;
      const dataUrl = canvas.toDataURL('image/png');
      if (isUsableDataUrl(dataUrl)) images[key] = dataUrl;
    } catch {
      // canvas tainted or empty — bỏ qua
    }
  }

  return images;
}

export function mergeChartImages(stored: ChartImages, fresh: ChartImages): ChartImages {
  return {
    typeGroup: fresh.typeGroup || stored.typeGroup,
    occurrence: fresh.occurrence || stored.occurrence,
    causeGroup: fresh.causeGroup || stored.causeGroup,
  };
}

export function countCapturedCharts(images: ChartImages): number {
  return CHART_KEYS.filter((k) => !!images[k]).length;
}

export function countExpectedCharts(expected: readonly (keyof ChartImages)[]): number {
  return expected.length;
}

export function hasAllExpectedCharts(
  images: ChartImages,
  expected: readonly (keyof ChartImages)[],
): boolean {
  if (expected.length === 0) return true;
  return expected.every((k) => !!images[k]);
}

/** Snapshot registry + DOM (registry trước — first print ổn định hơn). */
export function captureChartsSnapshot(stored: ChartImages = {}): ChartImages {
  return mergeChartImages(
    mergeChartImages(stored, captureChartsFromRegistry()),
    captureChartsFromAnalysisSection(),
  );
}

/** Đợi 2 frame paint — đủ để React commit print DOM trước In/Preview. */
export function flushPaint(): Promise<void> {
  return new Promise((resolve) => {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => resolve());
    });
  });
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Poll đến khi đủ chart kỳ vọng hoặc hết timeout (first-print / chart animation).
 * `expectedKeys` = các key có data (bỏ chart empty không mount).
 */
export async function captureChartsWithRetry(
  stored: ChartImages,
  opts?: {
    retries?: number;
    delayMs?: number;
    timeoutMs?: number;
    expectedKeys?: readonly (keyof ChartImages)[];
  },
): Promise<ChartImages> {
  const expected = opts?.expectedKeys ?? CHART_KEYS;
  const timeoutMs = opts?.timeoutMs ?? 3500;
  const delayMs = opts?.delayMs ?? 120;
  const deadline = Date.now() + timeoutMs;

  let merged = captureChartsSnapshot(stored);
  if (hasAllExpectedCharts(merged, expected)) return merged;

  while (Date.now() < deadline && !hasAllExpectedCharts(merged, expected)) {
    await sleep(delayMs);
    merged = captureChartsSnapshot(merged);
  }

  // Extra retries nếu vẫn thiếu (máy chậm)
  const retries = opts?.retries ?? 2;
  for (let i = 0; i < retries && !hasAllExpectedCharts(merged, expected); i++) {
    await sleep(delayMs * 2);
    merged = captureChartsSnapshot(merged);
  }

  return merged;
}
