import React, { useState } from 'react';
import type { MonthlyReportEditorViewModel } from './useMonthlyReportEditor';
import { Button } from '@linm-soft-org/linm-web-common-components';
import s from './MonthlyReportEditor.module.css';

type Props = Pick<
  MonthlyReportEditorViewModel,
  | 'draftLoading'
  | 'activeRpnCount'
  | 'periodLabel'
  | 'displayReportCode'
  | 'reportNumber'
  | 'onReportNumberChange'
  | 'readOnly'
  | 'draftSaving'
  | 'effectiveDateFrom'
  | 'effectiveDateTo'
  | 'handleSaveDraft'
  | 'handleSubmit'
  | 'handleDelete'
  | 'handleApprove'
  | 'handleCancel'
  | 'permissions'
  | 'showAiButton'
  | 'isAiEnabled'
  | 'aiLoading'
  | 'creditLoading'
  | 'handleAiAnalyze'
  | 'creditCheck'
  | 'nativeMob'
  | 'openPreview'
  | 'onPrintClick'
  | 'onExportWordClick'
  | 'exportingWord'
  | 'preparingPrint'
  | 'draftStatus'
>;

export const MonthlyReportEditorToolbar: React.FC<Props> = ({
  draftLoading,
  activeRpnCount,
  periodLabel,
  displayReportCode,
  reportNumber,
  onReportNumberChange,
  readOnly,
  draftSaving,
  effectiveDateFrom,
  effectiveDateTo,
  handleSaveDraft,
  handleSubmit,
  handleDelete,
  handleApprove,
  handleCancel,
  permissions,
  showAiButton,
  isAiEnabled,
  aiLoading,
  creditLoading,
  handleAiAnalyze,
  creditCheck,
  nativeMob,
  openPreview,
  onPrintClick,
  onExportWordClick,
  exportingWord,
  preparingPrint,
  draftStatus,
}) => {
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const isSubmitted = draftStatus === 'Submitted';
  const isApproved = draftStatus === 'Approved';
  const isDraft = draftStatus === 'Draft';
  const isNewOrDraft = !isSubmitted && !isApproved;

  return (
    <>
    <div className={s.toolbar}>
    <div className={s.toolbarInfo}>
      {draftLoading ? (
        <><i className="fas fa-spinner fa-spin" /><span>Đang tải bản lưu...</span></>
      ) : (
        <><i className="fas fa-lightbulb" />
        <span>
          <strong>{activeRpnCount}</strong> sự cố đã nhập · {periodLabel}
        </span></>
      )}
    </div>

    <div className={s.reportNumberWrapper} id="monthly-report-toolbar">
      <label className={s.reportNumberLabel} htmlFor="monthly-report-code">Mã BC:</label>
      <span className={s.reportCodeValue} id="monthly-report-code" title="Mã báo cáo tự sinh">
        {displayReportCode || '—'}
      </span>
      <label className={s.reportNumberLabel} htmlFor="monthly-report-display-number">Số hiển thị:</label>
      <input
        id="monthly-report-display-number"
        className={s.reportNumberInput}
        type="text"
        placeholder="11/2025"
        maxLength={50}
        value={reportNumber}
        disabled={readOnly}
        onChange={(e) => onReportNumberChange(e.target.value)}
        title="Số in trên đầu trang A4 (vd. 11/2025). Để trống sẽ dùng mã BC hoặc tháng/năm hiện tại."
      />
    </div>

    <div className={s.toolbarActions}>
      {/* ── Draft & New: Lưu nháp, Gửi ──────────────────────────────────── */}
      {!readOnly && isNewOrDraft && (
        <>
          {permissions?.canSaveDraft && (
            <button
              className={s.btnSaveDraft}
              onClick={() => void handleSaveDraft()}
              disabled={draftSaving || !effectiveDateFrom || !effectiveDateTo}
              title={!effectiveDateFrom ? 'Chọn kỳ báo cáo để lưu' : 'Lưu bản nháp'}
            >
              <i className={`fas ${draftSaving ? 'fa-spinner fa-spin' : 'fa-save'}`} />
              <span>{draftSaving ? 'Đang lưu...' : 'Lưu bản nháp'}</span>
            </button>
          )}
          {permissions?.canSubmit && (
            <button
              className={s.btnSaveDraft}
              style={{ borderColor: '#2563eb', background: '#eff6ff', color: '#1d4ed8' }}
              onClick={() => void handleSubmit()}
              disabled={draftSaving || !effectiveDateFrom || !effectiveDateTo}
              title="Gửi báo cáo (trình ký)"
            >
              <i className={`fas ${draftSaving ? 'fa-spinner fa-spin' : 'fa-paper-plane'}`} />
              <span>{draftSaving ? 'Đang gửi...' : 'Gửi báo cáo'}</span>
            </button>
          )}
        </>
      )}

      {/* ── Draft only: Xóa, Phân tích AI ────────────────────────────────── */}
      {!readOnly && isDraft && (
        <>
          {permissions?.canDelete && !draftLoading && (
            <button
              type="button"
              className={s.btnSaveDraft}
              style={{ borderColor: '#ef4444', background: '#fef2f2', color: '#dc2626' }}
              onClick={() => setShowDeleteConfirm(true)}
              title="Xóa báo cáo nháp"
            >
              <i className="fas fa-trash-alt" />
              <span>Xóa</span>
            </button>
          )}
          {showAiButton && isAiEnabled && (
            <button
              type="button"
              className={s.btnAiEnabled}
              data-testid="medical-report-ai-analyze-btn"
              disabled={aiLoading || creditLoading}
              onClick={() => void handleAiAnalyze()}
              title={
                creditCheck
                  ? `${creditCheck.balance} credit · cần ${creditCheck.requiredCredits}/lần`
                  : 'Phân tích AI'
              }
            >
              <i className={`fas ${aiLoading ? 'fa-spinner fa-spin' : 'fa-robot'}`} />
              <span>{aiLoading ? 'Đang phân tích...' : 'Phân tích với AI'}</span>
              {creditCheck && !creditLoading && (
                <span className={s.creditBadge}>{creditCheck.balance} credit</span>
              )}
            </button>
          )}
          {showAiButton && !isAiEnabled && (
            <button
              type="button"
              className={s.btnAi}
              data-testid="medical-report-ai-coming-soon-btn"
              disabled
              title="Tính năng phân tích AI sẽ được bật sau"
            >
              <i className="fas fa-robot" />
              <span>Phân tích với AI</span>
              <span className={s.aiComingSoon}>Sắp có</span>
            </button>
          )}
        </>
      )}

      {/* ── Submitted (chưa duyệt): Hủy, Duyệt, Xem trước A4, Tải Word, In báo cáo ──── */}
      {isSubmitted && (
        <>
          {permissions?.canCancel && !readOnly && (
            <button
              type="button"
              className={s.btnSaveDraft}
              style={{ borderColor: '#f59e0b', background: '#fffbeb', color: '#b45309' }}
              onClick={() => setShowCancelConfirm(true)}
              title="Hủy gửi, trả về bản nháp"
            >
              <i className="fas fa-undo-alt" />
              <span>Hủy gửi</span>
            </button>
          )}
          {permissions?.canApprove && !readOnly && (
            <button
              type="button"
              className={s.btnSaveDraft}
              style={{ borderColor: '#059669', background: '#ecfdf5', color: '#047857' }}
              onClick={() => void handleApprove()}
              title="Duyệt báo cáo"
            >
              <i className="fas fa-check-circle" />
              <span>Duyệt</span>
            </button>
          )}
          {!nativeMob && (
        <button
          type="button"
          className={s.btnSecondary}
          onClick={() => void openPreview()}
          disabled={preparingPrint || exportingWord}
        >
          <i className={`fas ${preparingPrint ? 'fa-spinner fa-spin' : 'fa-eye'}`} />
          <span>{preparingPrint ? 'Đang chuẩn bị...' : 'Xem trước A4'}</span>
        </button>
      )}
      <button
        type="button"
        className={s.btnExportWord}
        onClick={() => void onExportWordClick()}
        disabled={exportingWord || preparingPrint}
        data-testid="monthly-report-export-word-btn"
        title="Tải báo cáo định dạng Word (.docx)"
      >
        <i className={`fas ${exportingWord ? 'fa-spinner fa-spin' : 'fa-file-word'}`} />
        <span>{exportingWord ? 'Đang xuất...' : 'Tải Word'}</span>
      </button>
      <button
        type="button"
        className={s.btnPrint}
        onClick={() => void onPrintClick()}
        disabled={preparingPrint || exportingWord}
        title={preparingPrint ? 'Đang chuẩn bị biểu đồ...' : undefined}
      >
        <i className={`fas ${preparingPrint ? 'fa-spinner fa-spin' : nativeMob ? 'fa-download' : 'fa-print'}`} />
        <span>
          {preparingPrint ? 'Đang chuẩn bị...' : nativeMob ? 'Tải PDF' : 'In báo cáo'}
        </span>
      </button>
        </>
      )}
    </div>

    {/* ── Delete confirm dialog ────────────────────────────────────────── */}
    {showDeleteConfirm && (
      <div className={s.overlay}>
        <div className={s.dialog}>
          <h3>Xác nhận xóa</h3>
          <p>
            Bạn có chắc muốn xóa báo cáo{' '}
            <strong>{displayReportCode || 'này'}</strong>?<br />
            Hành động này không thể hoàn tác.
          </p>
          <div className={s.dialogActions}>
            <Button variant="secondary" onClick={() => setShowDeleteConfirm(false)}>
              Hủy
            </Button>
            <Button
              variant="danger"
              onClick={() => {
                setShowDeleteConfirm(false);
                void handleDelete();
              }}
            >
              <i className="fas fa-trash" /> Xóa
            </Button>
          </div>
        </div>
      </div>
    )}

    {/* ── Cancel submission confirm dialog ──────────────────────────────── */}
    {showCancelConfirm && (
      <div className={s.overlay}>
        <div className={s.dialog}>
          <h3>Xác nhận hủy gửi</h3>
          <p>
            Bạn có chắc muốn hủy gửi báo cáo{' '}
            <strong>{displayReportCode || 'này'}</strong>?<br />
            Báo cáo sẽ trở về trạng thái nháp.
          </p>
          <div className={s.dialogActions}>
            <Button variant="secondary" onClick={() => setShowCancelConfirm(false)}>
              Đóng
            </Button>
            <Button
              variant="danger"
              onClick={() => {
                setShowCancelConfirm(false);
                void handleCancel();
              }}
            >
              <i className="fas fa-undo-alt" /> Hủy gửi
            </Button>
          </div>
        </div>
      </div>
    )}
  </div>
    </>
  );
}
