export async function exportMonthlyReportToDocx(
  printRoot: HTMLElement,
  options: {
    periodLabel: string;
    reportCode?: string;
    chartImages?: ChartImages;
  },
): Promise<void> {
  // Prefer caller-prepared images (prepareChartImagesForExport); still merge fresh canvas.
  const freshCharts = captureChartsFromAnalysisSection();
  const mergedCharts = mergeChartImages(options.chartImages ?? {}, freshCharts);

  const fileName = buildSafeDocxFileName('BCSC', [
    options.periodLabel,
    options.reportCode || '',
  ]);

  await downloadElementAsDocx(printRoot, {
    docCss: MONTHLY_REPORT_DOCX_CSS,
    bodyStyle: DOCX_BODY_STYLE,
    fileName,
    chartImages: mergedCharts as Record<string, string | undefined>,
  });
}
