/** Lề A4 văn bản hành chính VN (mm) — khớp `.document` padding preview+print (@page margin: 0). */
export const DOCX_A4_MARGINS_MM = {
  top: 20,
  right: 15,
  bottom: 20,
  left: 30,
} as const;

/** html-to-docx (Node) — twips · 1mm ≈ 56.6929 twips */
export const DOCX_DOCUMENT_MARGINS_TWIPS = {
  top: 1134,
  right: 850,
  bottom: 1134,
  left: 1701,
} as const;

export const DOCX_FONT_FAMILY = "'Times New Roman',Times,serif";

export const DOCX_BODY_STYLE = `font-family:${DOCX_FONT_FAMILY};font-size:12pt;line-height:1.45;color:#000;margin:0;padding:0`;

/** @page + body zero margin — lề do section padding hoặc Word page setup. */
export function buildDocxPageCss(margins = DOCX_A4_MARGINS_MM): string {
  const { top, right, bottom, left } = margins;
  return `
@page {
  size: A4 portrait;
  margin: ${top}mm ${right}mm ${bottom}mm ${left}mm;
}
body {
  margin: 0;
  padding: 0;
}
`.trim();
}

/** Wrapper nội dung — padding = lề khi engine Word bỏ qua @page. */
export function buildDocxContentPaddingStyle(margins = DOCX_A4_MARGINS_MM): string {
  const { top, right, bottom, left } = margins;
  return `padding:${top}mm ${right}mm ${bottom}mm ${left}mm;box-sizing:border-box;width:100%;max-width:210mm;margin:0 auto;background:#fff`;
}
