import type { MonthlyReportRpnRow } from '../models/MedicalIncident';
import type { ValidationErrors, ValidationRule } from './formValidation';

export type MonthlyReportSaveForm = {
  dateFrom: string;
  dateTo: string;
  reportNumber: string;
  typeGroupChartType: string;
  occurrenceChartType: string;
  causeGroupChartType: string;
  rpnRows: MonthlyReportRpnRow[];
};

const CHART_TYPES = new Set(['doughnut', 'bar-v', 'bar-h']);

function parseIsoDate(value: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const d = new Date(`${value}T00:00:00`);
  return Number.isNaN(d.getTime()) ? null : d;
}

function validateRpnScore(value: number | null | undefined, label: string): string | null {
  if (value == null) return null;
  if (!Number.isInteger(value) || value < 1 || value > 10) {
    return `${label} phải là số nguyên từ 1 đến 10`;
  }
  return null;
}

export const MONTHLY_REPORT_SAVE_RULES: ValidationRule<MonthlyReportSaveForm>[] = [
  {
    field: 'dateFrom',
    sectionId: 'monthly-report-filter-bar',
    validate: (f) => (!f.dateFrom?.trim() ? 'Từ ngày là bắt buộc' : null),
  },
  {
    field: 'dateTo',
    sectionId: 'monthly-report-filter-bar',
    validate: (f) => (!f.dateTo?.trim() ? 'Đến ngày là bắt buộc' : null),
  },
  {
    field: 'dateFrom',
    sectionId: 'monthly-report-filter-bar',
    validate: (f) => {
      if (!f.dateFrom || !f.dateTo) return null;
      const from = parseIsoDate(f.dateFrom);
      const to = parseIsoDate(f.dateTo);
      if (!from || !to) return 'Ngày không hợp lệ (định dạng YYYY-MM-DD)';
      if (from > to) return 'Từ ngày phải nhỏ hơn hoặc bằng đến ngày';
      return null;
    },
  },
  {
    field: 'reportNumber',
    sectionId: 'monthly-report-toolbar',
    validate: (f) => {
      const n = f.reportNumber?.trim() ?? '';
      if (n.length > 50) return 'Số hiển thị tối đa 50 ký tự';
      return null;
    },
  },
  {
    field: 'typeGroupChartType',
    sectionId: 'monthly-report-section-analysis',
    validate: (f) =>
      !CHART_TYPES.has(f.typeGroupChartType ?? '')
        ? 'Loại biểu đồ nhóm sự cố không hợp lệ'
        : null,
  },
  {
    field: 'occurrenceChartType',
    sectionId: 'monthly-report-section-analysis',
    validate: (f) =>
      !CHART_TYPES.has(f.occurrenceChartType ?? '')
        ? 'Loại biểu đồ mức độ không hợp lệ'
        : null,
  },
  {
    field: 'causeGroupChartType',
    sectionId: 'monthly-report-section-analysis',
    validate: (f) =>
      !CHART_TYPES.has(f.causeGroupChartType ?? '')
        ? 'Loại biểu đồ nguyên nhân không hợp lệ'
        : null,
  },
];

/** Row-level RPN validation — returns first error message or null. */
export function validateMonthlyReportRpnRows(rows: MonthlyReportRpnRow[]): string | null {
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    const hasName = Boolean(row.incidentName?.trim());
    const hasScores = row.s != null || row.o != null || row.d != null;
    if (!hasName && !hasScores) continue;

    if (hasName && hasScores) {
      for (const [field, label] of [
        ['s', 'S'] as const,
        ['o', 'O'] as const,
        ['d', 'D'] as const,
      ]) {
        const err = validateRpnScore(row[field], label);
        if (err) return `Dòng ${i + 1}: ${err}`;
      }
      if (row.s == null || row.o == null || row.d == null) {
        return `Dòng ${i + 1}: nhập đủ S, O, D (1–10) khi đã đặt tên sự cố`;
      }
    } else if (hasName && (row.s != null || row.o != null || row.d != null)) {
      return `Dòng ${i + 1}: nhập đủ S, O, D (1–10) khi đã đặt tên sự cố`;
    } else if (!hasName && hasScores) {
      return `Dòng ${i + 1}: nhập tên sự cố khi đã chấm S/O/D`;
    }
  }
  return null;
}

export function mergeRpnValidationErrors(
  base: ValidationErrors,
  rpnError: string | null,
): ValidationErrors {
  if (!rpnError) return base;
  return { ...base, rpnRows: rpnError };
}
