/**
 * AI credit + monthly report analysis — BFF proxy to Linm.AI.WebService
 */
import { apiClient } from '../api';
import { postBffWithStatus } from '../shared/bffPostWithStatus';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  AiCreditCheckResult,
  AiGenerateAnalyzeRequest,
  AiGenerateAnalyzeResponse,
  AiInsufficientCreditError,
} from './types';

export const MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE =
  'medical-incident-monthly-report';

const BASE = '/medical-incidents/ai';

export const medicalIncidentsAiEndpoint = {
  checkCredits: async (
    featureKey = MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE,
  ): Promise<AiCreditCheckResult> => {
    const res = await apiClient.get<BffResponse<AiCreditCheckResult>>(
      `${BASE}/credits/check?featureKey=${encodeURIComponent(featureKey)}`,
    );
    return unwrap(res);
  },

  analyzeReport: async (
    body: AiGenerateAnalyzeRequest,
    requestId?: string,
  ): Promise<AiGenerateAnalyzeResponse> => {
    const { status, json } = await postBffWithStatus<Record<string, unknown>>(
      `${BASE}/reports/analyze`,
      body,
      requestId ? { 'X-Request-Id': requestId } : undefined,
    );

    if (status === 402) {
      const err: AiInsufficientCreditError = {
        status: 402,
        message: (json?.message as string | undefined) ?? 'AI_CREDIT_INSUFFICIENT',
        data: json?.data as AiInsufficientCreditError['data'],
      };
      throw err;
    }

    if (status < 200 || status >= 300) {
      throw new Error(
        (json?.error as { toastMessage?: string } | undefined)?.toastMessage ||
          (json?.message as string | undefined) ||
          'Phân tích AI thất bại',
      );
    }

    return unwrap(json as unknown as BffResponse<AiGenerateAnalyzeResponse>);
  },
};
