import React, { useMemo } from 'react';
import { Button, Modal } from '@linm-soft-org/linm-web-common-components';
import type { AiCreditCheckResult, AiCreditPack } from '../../../services/medicalIncidentsAi/types';
import type { MedicalIncidentReport } from '../../../models/MedicalIncident';
import {
  PrintableRecommendationDoc,
  type ChartImages,
  type AiAnalysisOverride,
  type RpnRow,
} from './PrintableRecommendationDoc';
import type { MedicalIncidentReportFilters, IncidentReportSummaryItem } from '../../../models/MedicalIncident';
import s from './MonthlyReportEditor.module.css';

/** A4 width at 96dpi — dùng tính scale preview (khớp `.document { width: 210mm }`). */
export const A4_PREVIEW_WIDTH_PX = 794;

interface Props {
  report: MedicalIncidentReport;
  printRef: React.RefObject<HTMLDivElement>;
  previewScrollRef: React.RefObject<HTMLDivElement>;
  effectiveFilters: MedicalIncidentReportFilters;
  rpnRows: RpnRow[];
  chartImages: ChartImages;
  displayReportCode: string;
  reportNumber: string;
  effectiveOverride: AiAnalysisOverride;
  aiDraftApplied: boolean;
  summaryItems: IncidentReportSummaryItem[];
  showPreview: boolean;
  setShowPreview: (open: boolean) => void;
  zoom: number;
  periodLabel: string;
  onPrintClick: () => void | Promise<void>;
  onExportWordClick: () => void | Promise<void>;
  exportingWord: boolean;
  preparingPrint?: boolean;
  isAiEnabled: boolean;
  showCreditModal: boolean;
  setShowCreditModal: (open: boolean) => void;
  creditCheck: AiCreditCheckResult | null;
  suggestedPacks: AiCreditPack[];
}

export const MonthlyReportEditorOverlays: React.FC<Props> = ({
  report,
  printRef,
  previewScrollRef,
  effectiveFilters,
  rpnRows,
  chartImages,
  displayReportCode,
  reportNumber,
  effectiveOverride,
  aiDraftApplied,
  summaryItems,
  showPreview,
  setShowPreview,
  zoom,
  periodLabel,
  onPrintClick,
  onExportWordClick,
  exportingWord,
  preparingPrint = false,
  isAiEnabled,
  showCreditModal,
  setShowCreditModal,
  creditCheck,
  suggestedPacks,
}) => {
  /** Cùng props cho bản in (hidden) và xem trước — tránh lệch số BC / nội dung. */
  const docProps = useMemo(
    () => ({
      report,
      filters: effectiveFilters,
      rpnRows,
      chartImages,
      reportCode: displayReportCode || undefined,
      reportNumber: reportNumber.trim() || undefined,
      analysisOverride: effectiveOverride,
      aiDraftLabel: aiDraftApplied,
      summaryItems,
    }),
    [
      report,
      effectiveFilters,
      rpnRows,
      chartImages,
      displayReportCode,
      reportNumber,
      effectiveOverride,
      aiDraftApplied,
      summaryItems,
    ],
  );

  return (
    <>
      <div className={s.printHidden}>
        <PrintableRecommendationDoc ref={printRef} {...docProps} />
      </div>

      {showPreview && (
        <div className={s.previewOverlay} onClick={() => setShowPreview(false)}>
          <div className={s.previewModal} onClick={(e) => e.stopPropagation()}>
            <div className={s.previewModalHeader}>
              <span>
                <i className="fas fa-eye" style={{ marginRight: 6 }} />
                Xem trước A4 — {periodLabel}
                <span style={{ fontWeight: 400, opacity: 0.75, marginLeft: 8 }}>
                  (cùng layout / lề với bản in)
                </span>
              </span>
              <div style={{ display: 'flex', gap: 8 }}>
                <button
                  type="button"
                  className={s.btnExportWord}
                  onClick={() => void onExportWordClick()}
                  disabled={exportingWord || preparingPrint}
                >
                  <i className={`fas ${exportingWord ? 'fa-spinner fa-spin' : 'fa-file-word'}`} />
                  Tải Word
                </button>
                <button
                  type="button"
                  className={s.btnPrint}
                  onClick={() => void onPrintClick()}
                  disabled={preparingPrint || exportingWord}
                >
                  <i className={`fas ${preparingPrint ? 'fa-spinner fa-spin' : 'fa-print'}`} />
                  {preparingPrint ? 'Đang chuẩn bị...' : 'In / Lưu PDF'}
                </button>
                <button type="button" className={s.previewCloseBtn} onClick={() => setShowPreview(false)}>
                  <i className="fas fa-times" />
                </button>
              </div>
            </div>
            <div className={s.previewScroll} ref={previewScrollRef}>
              {/*
                CSS zoom (không phải transform) — thu nhỏ hiển thị nhưng giữ cùng
                box model 210mm + padding NĐ 30 như bản in (@page margin: 0).
              */}
              <div className={s.previewScale} style={{ zoom }}>
                <PrintableRecommendationDoc {...docProps} />
              </div>
            </div>
          </div>
        </div>
      )}

      {isAiEnabled && (
        <Modal
          isOpen={showCreditModal}
          onClose={() => setShowCreditModal(false)}
          title="Không đủ credit AI"
          size="sm"
          data-testid="medical-report-ai-credit-modal"
        >
          <div className={s.creditModalBody}>
            <p className={s.creditModalIntro}>
              Phân tích báo cáo SCYK cần{' '}
              <strong>{creditCheck?.requiredCredits ?? 20} credit</strong>
              {creditCheck != null && (
                <> — bạn còn <strong>{creditCheck.balance}</strong> credit.</>
              )}
            </p>
            <div className={s.creditPackList}>
              {(suggestedPacks.length > 0 ? suggestedPacks : creditCheck?.suggestedPackages ?? []).map(
                (pack) => (
                  <div
                    key={pack.packId}
                    className={`${s.creditPackItem} ${pack.recommended ? s.creditPackItemRecommended : ''}`}
                  >
                    <div>
                      <span className={s.creditPackLabel}>{pack.label}</span>
                      {pack.recommended && <span className={s.creditPackTag}>Đề xuất</span>}
                    </div>
                    <span className={s.creditPackPrice}>
                      {pack.priceVnd.toLocaleString('vi-VN')} ₫
                    </span>
                  </div>
                ),
              )}
            </div>
            <Button variant="secondary" onClick={() => setShowCreditModal(false)}>
              Đóng
            </Button>
          </div>
        </Modal>
      )}
    </>
  );
};
