/**
 * Inline computed styles for Word — html-docx-js ignores CSS modules / flex.
 * Parity print preview (In A4). Skill: /implement-export-html-to-doc
 */
import { DOCX_FONT, finalizeDocxTypography, pxFontSizeToPt } from './docxTypography';
import { normalizeDocxTables } from './docxTableFix';

const STYLE_PROPS: Array<[keyof CSSStyleDeclaration, string]> = [
  ['textAlign', 'text-align'],
  ['fontWeight', 'font-weight'],
  ['fontSize', 'font-size'],
  ['fontStyle', 'font-style'],
  ['textDecoration', 'text-decoration'],
  ['verticalAlign', 'vertical-align'],
  ['lineHeight', 'line-height'],
  ['textTransform', 'text-transform'],
  ['color', 'color'],
];

function appendStyle(el: HTMLElement, extra: string): void {
  const prev = el.getAttribute('style') || '';
  el.setAttribute('style', prev ? `${prev};${extra}` : extra);
}

function stripCellWidthPercent(el: HTMLElement): void {
  if (el.tagName !== 'TH' && el.tagName !== 'TD') return;
  const w = el.style.width || '';
  if (w.includes('%')) {
    el.style.removeProperty('width');
  }
}

function computedInlineExtras(source: HTMLElement, target: HTMLElement): string {
  const cs = window.getComputedStyle(source);
  const parts: string[] = [DOCX_FONT];

  for (const [jsKey, cssKey] of STYLE_PROPS) {
    const raw = cs[jsKey] as string;
    if (!raw || raw === 'normal' || raw === 'none' || raw === 'auto') continue;
    if (jsKey === 'fontWeight' && (raw === '400' || raw === '300')) continue;
    if (jsKey === 'color' && (raw === 'rgb(0, 0, 0)' || raw === 'rgba(0, 0, 0, 0)')) continue;
    if (jsKey === 'fontSize') {
      parts.push(`${cssKey}:${pxFontSizeToPt(raw)}`);
      continue;
    }
    parts.push(`${cssKey}:${raw}`);
  }

  if (target.tagName === 'TABLE') {
    parts.push(
      'width:100%',
      'border-collapse:collapse',
      'border-spacing:0',
      'border:1px solid #000',
      'font-size:11pt',
      'margin-top:6px',
    );
  }
  if (target.tagName === 'TH') {
    parts.push(
      'border:1px solid #000',
      'padding:5px 8px',
      'font-weight:bold',
      'text-align:center',
      'font-size:11pt',
    );
  }
  if (target.tagName === 'TD') {
    parts.push('border:1px solid #000', 'padding:5px 8px', 'font-size:11pt', 'vertical-align:top');
  }

  return parts.join(';');
}

/** Walk source + clone cùng cấu trúc — gắn inline style từ getComputedStyle. */
export function inlineComputedStylesFromSource(source: Element, clone: Element): void {
  if (!(source instanceof HTMLElement) || !(clone instanceof HTMLElement)) return;

  const extra = computedInlineExtras(source, clone);
  if (extra) appendStyle(clone, extra);
  stripCellWidthPercent(clone);

  const srcChildren = Array.from(source.children);
  const cloneChildren = Array.from(clone.children);
  srcChildren.forEach((srcChild, i) => {
    if (cloneChildren[i]) {
      inlineComputedStylesFromSource(srcChild, cloneChildren[i]);
    }
  });
}

/** Flex header → table 2 cột (Word không hỗ trợ flex). */
export function convertPageHeaderFlexToTable(clone: HTMLElement): void {
  clone.querySelectorAll('[data-lin-docx-page-header]').forEach((header) => {
    const left = header.querySelector('[data-lin-docx-header-col="left"]');
    const right = header.querySelector('[data-lin-docx-header-col="right"]');
    if (!left || !right) return;

    const table = document.createElement('table');
    appendStyle(
      table,
      `width:100%;border-collapse:collapse;border:none;margin-bottom:4px;${DOCX_FONT};font-size:10pt`,
    );

    const tr = document.createElement('tr');
    const tdL = document.createElement('td');
    appendStyle(
      tdL,
      `width:45%;vertical-align:top;text-align:left;border:none;padding:0;${DOCX_FONT};font-size:10pt;line-height:1.5`,
    );
    tdL.innerHTML = left.innerHTML;

    const tdR = document.createElement('td');
    appendStyle(
      tdR,
      `width:55%;vertical-align:top;text-align:center;border:none;padding:0;${DOCX_FONT};font-size:10pt;line-height:1.5`,
    );
    tdR.innerHTML = right.innerHTML;

    tr.appendChild(tdL);
    tr.appendChild(tdR);
    table.appendChild(tr);
    header.replaceWith(table);
  });
}

/** Flex pctRow fallback → bảng 2 cột cho Word. */
export function convertPctRowsToTables(clone: HTMLElement): void {
  clone.querySelectorAll('[data-lin-docx-pct-row]').forEach((row) => {
    const label = row.querySelector('[data-lin-docx-pct-label]');
    const value = row.querySelector('[data-lin-docx-pct-value]');
    if (!label || !value) return;

    const table = document.createElement('table');
    appendStyle(
      table,
      `width:100%;border-collapse:collapse;border:1px solid #ccc;margin:0;${DOCX_FONT};font-size:11pt`,
    );

    const tr = document.createElement('tr');
    const tdL = document.createElement('td');
    appendStyle(
      tdL,
      `${DOCX_FONT};font-size:11pt;text-align:left;border:1px solid #ccc;padding:3px 10px;width:70%`,
    );
    tdL.textContent = label.textContent || '';

    const tdR = document.createElement('td');
    appendStyle(
      tdR,
      `${DOCX_FONT};font-size:11pt;text-align:right;font-weight:bold;border:1px solid #ccc;padding:3px 10px;width:30%`,
    );
    tdR.textContent = value.textContent || '';

    tr.appendChild(tdL);
    tr.appendChild(tdR);
    table.appendChild(tr);
    row.replaceWith(table);
  });
}

/** Chữ ký 2 cột trái/phải → table (Word cấm flex/grid). */
export function convertSignatureRowToTable(clone: HTMLElement): void {
  clone.querySelectorAll('[data-lin-docx-signature-row]').forEach((row) => {
    const left = row.querySelector('[data-lin-docx-signature-col="left"]');
    const right = row.querySelector('[data-lin-docx-signature-col="right"]');
    if (!left || !right) return;

    const table = document.createElement('table');
    appendStyle(
      table,
      `width:100%;border-collapse:collapse;border:none;margin-top:24px;${DOCX_FONT}`,
    );

    const tr = document.createElement('tr');
    const tdL = document.createElement('td');
    appendStyle(
      tdL,
      `width:50%;vertical-align:top;text-align:center;border:none;padding:0 12px 0 0;${DOCX_FONT}`,
    );
    tdL.innerHTML = left.innerHTML;

    const tdR = document.createElement('td');
    appendStyle(
      tdR,
      `width:50%;vertical-align:top;text-align:center;border:none;padding:0 0 0 12px;${DOCX_FONT}`,
    );
    tdR.innerHTML = right.innerHTML;

    tr.appendChild(tdL);
    tr.appendChild(tdR);
    table.appendChild(tr);
    row.replaceWith(table);
  });
}

export function applyDocxLayoutFixes(source: HTMLElement, clone: HTMLElement): void {
  inlineComputedStylesFromSource(source, clone);
  convertPageHeaderFlexToTable(clone);
  convertPctRowsToTables(clone);
  convertSignatureRowToTable(clone);
  finalizeDocxTypography(clone);
  normalizeDocxTables(clone);
}
