import React, { useCallback, useEffect, useRef } from 'react';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  BAR_OPTIONS_HORIZONTAL,
} from '../../MedicalIncidentReportPage/chartUtils';
import { registerChartCapture } from '../../../utils/chartCaptureForDocx';
import type { ChartDisplayType } from './monthlyReportEditorShared';
import s from './MonthlyReportEditor.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

const CHART_TYPE_OPTIONS: { key: ChartDisplayType; icon: string; label: string }[] = [
  { key: 'doughnut', icon: 'fas fa-circle-notch', label: 'Tròn' },
  { key: 'bar-v',    icon: 'fas fa-chart-bar',    label: 'Cột dọc' },
  { key: 'bar-h',    icon: 'fas fa-grip-lines',   label: 'Cột ngang' },
];

/** HTML legend with color chips, rendered at 13px — replaces built-in Chart.js 11px legend. */
export const ChartLegend: React.FC<{
  labels: string[];
  counts: number[];
  total: number;
  colors: readonly string[];
  visible?: boolean;
}> = ({ labels, counts, total, colors, visible = true }) => {
  if (!visible || labels.length === 0) return null;
  return (
    <div className={s.chartLegend}>
      {labels.map((label, i) => {
        const pct = total > 0 ? ((counts[i] / total) * 100).toFixed(1) : '0';
        return (
          <div key={i} className={s.chartLegendItem}>
            <span
              className={s.chartLegendChip}
              data-color={colors[i % colors.length]}
              style={{ backgroundColor: colors[i % colors.length] }}
            >&nbsp;</span>
            <span className={s.chartLegendLabel}>{label}</span>
            <span className={s.chartLegendValue}>{counts[i]} ({pct}%)</span>
          </div>
        );
      })}
    </div>
  );
};

export const ChartTypeSelector: React.FC<{
  value: ChartDisplayType;
  onChange: (v: ChartDisplayType) => void;
  disabled?: boolean;
}> = ({ value, onChange, disabled = false }) => (
  <div className={s.chartTypeSelector}>
    {CHART_TYPE_OPTIONS.map((opt) => (
      <button
        key={opt.key}
        type="button"
        disabled={disabled}
        className={`${s.chartTypeSelectorBtn} ${value === opt.key ? s.chartTypeSelectorBtnActive : ''}`}
        onClick={() => !disabled && onChange(opt.key)}
        title={opt.label}
      >
        <i className={opt.icon} />
        <span>{opt.label}</span>
      </button>
    ))}
  </div>
);

interface DynamicChartProps {
  type:      ChartDisplayType;
  labels:    string[];
  data:      number[];
  onCapture: (base64: string) => void;
  showLegend?: boolean;
  /** Key ổn định cho capture (In/Preview/Word) — gắn `data-chart-key`. */
  chartKey?: 'typeGroup' | 'occurrence' | 'causeGroup';
}

export const DynamicChart: React.FC<DynamicChartProps> = ({
  type,
  labels,
  data,
  onCapture,
  showLegend = true,
  chartKey,
}) => {
  const chartRef = useRef<ChartJS>(null);

  const captureNow = useCallback(() => {
    const chart = chartRef.current;
    if (!chart) return;
    try {
      // resize trước khi capture — hidden section đôi khi size 0 lần đầu
      chart.resize();
      const b64 = chart.toBase64Image('image/png', 1);
      if (b64?.startsWith('data:image') && b64.length > 100) onCapture(b64);
    } catch {
      // ignore
    }
  }, [onCapture]);

  // Registry — In lần đầu đọc trực tiếp instance, không phụ thuộc timing DOM.
  useEffect(() => {
    if (!chartKey) return undefined;
    return registerChartCapture(chartKey, () => {
      const chart = chartRef.current;
      if (!chart) return null;
      try {
        chart.resize();
        const b64 = chart.toBase64Image('image/png', 1);
        return b64?.startsWith('data:image') && b64.length > 100 ? b64 : null;
      } catch {
        return null;
      }
    });
  }, [chartKey]);

  // Capture sau mount / đổi data — một lần đủ (registry dùng cho In).
  useEffect(() => {
    let cancelled = false;
    const id = window.setTimeout(() => {
      if (!cancelled) captureNow();
    }, 80);
    return () => {
      cancelled = true;
      window.clearTimeout(id);
    };
  }, [type, labels.join('\0'), data.join(','), captureNow]);

  const colors = data.map((_, i) => CHART_COLORS[i % CHART_COLORS.length]);

  const chartData = {
    labels,
    datasets: [{
      data,
      backgroundColor: colors,
      borderColor:     type === 'doughnut' ? '#fff' : colors,
      borderWidth:     type === 'doughnut' ? 2 : 1,
    }],
  };

  const total = data.reduce((a, b) => a + b, 0);

  const baseOptions = type === 'doughnut'
    ? { ...DOUGHNUT_OPTIONS, plugins: { ...DOUGHNUT_OPTIONS.plugins, legend: { display: false } } }
    : type === 'bar-v'
      ? BAR_OPTIONS_VERTICAL
      : BAR_OPTIONS_HORIZONTAL;

  // animation: false — first print không chờ animation; capture ổn định ngay sau mount
  const options = {
    ...baseOptions,
    animation: false as const,
  };

  const chartEl = type === 'doughnut' ? (
    <Doughnut
      ref={chartRef as React.RefObject<ChartJS<'doughnut'>>}
      data={chartData as Parameters<typeof Doughnut>[0]['data']}
      options={options as Parameters<typeof Doughnut>[0]['options']}
    />
  ) : (
    <Bar
      ref={chartRef as React.RefObject<ChartJS<'bar'>>}
      data={chartData as Parameters<typeof Bar>[0]['data']}
      options={options as Parameters<typeof Bar>[0]['options']}
    />
  );

  return (
    <div data-chart-key={chartKey || undefined}>
      {chartEl}
      {showLegend && (
        <ChartLegend
          labels={labels}
          counts={data}
          total={total}
          colors={CHART_COLORS}
        />
      )}
    </div>
  );
};
