import React from 'react';
import type { RpnRow } from './PrintableRecommendationDoc';
import s from './MonthlyReportEditor.module.css';

interface Props {
  readOnly: boolean;
  rpnRows: RpnRow[];
  updateRpn: (idx: number, field: keyof RpnRow, value: string) => void;
}

export const MonthlyReportSectionSolution: React.FC<Props> = ({
  readOnly,
  rpnRows,
  updateRpn,
}) => {
  const namedRows = rpnRows.filter((r) => r.incidentName.trim());

  if (namedRows.length === 0) {
    return (
      <div className={s.solutionSection}>
        <div className={s.solutionEmpty}>
          <i className="fas fa-arrow-left" style={{ marginRight: 8 }} />
          Vào <strong>Mục 3 — Trầm trọng</strong> nhập tên sự cố trước, sau đó quay lại đây để điền nguyên nhân và đề xuất.
        </div>
      </div>
    );
  }

  return (
    <div className={s.solutionSection}>
      <div className={s.solutionHeader}>
        <div className={s.solutionDescription}>
          <i className="fas fa-info-circle" style={{ color: '#3b82f6', marginRight: 6 }} />
          Nhập nguyên nhân chi tiết và đề xuất giải pháp cho từng sự cố.
          Sẽ in ở <strong>Mục 4</strong> của báo cáo.
        </div>
      </div>

      <div className={s.solutionCards}>
        {rpnRows.map((row, idx) => {
          if (!row.incidentName.trim()) return null;

          return (
            <div key={idx} className={s.solutionCard}>
              {/* Row 1: Full-width incident name */}
              <div className={s.solutionCardHeader}>
                <span className={s.solutionCardIndex}>{idx + 1}</span>
                <span className={s.solutionCardTitle}>{row.incidentName}</span>
              </div>
              {/* Row 2: Cause | Solution */}
              <div className={s.solutionCardBody}>
                <div className={s.solutionCardField}>
                  <label className={s.solutionFieldLabel}>
                    <i className="fas fa-exclamation-triangle" style={{ color: '#f59e0b' }} />
                    Nguyên nhân chi tiết
                    <span className={s.solutionFieldHint}>(dựa trên chuyên gia đánh giá)</span>
                  </label>
                  <textarea
                    className={s.solutionCauseInput}
                    rows={4}
                    readOnly={readOnly}
                    placeholder="Mô tả nguyên nhân cụ thể gây ra sự cố này..."
                    value={row.causeDetail}
                    onChange={(e) => updateRpn(idx, 'causeDetail', e.target.value)}
                  />
                </div>
                <div className={s.solutionCardField}>
                  <label className={s.solutionFieldLabel}>
                    <i className="fas fa-lightbulb" style={{ color: '#10b981' }} />
                    Đề xuất giải pháp
                    <span className={s.solutionFieldHint}>(dựa trên chuyên gia đánh giá)</span>
                  </label>
                  <textarea
                    className={s.solutionSolutionInput}
                    rows={5}
                    readOnly={readOnly}
                    placeholder={'Nhập đề xuất giải pháp phòng ngừa...\n\nVí dụ:\n- Tổ chức đào tạo lại quy trình\n- Tăng cường kiểm tra định kỳ'}
                    value={row.solution}
                    onChange={(e) => updateRpn(idx, 'solution', e.target.value)}
                  />
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>);
};
