import { useCallback, useEffect, useRef, useState, type Dispatch, type SetStateAction } from 'react';
import { flushSync } from 'react-dom';
import { useReactToPrint } from 'react-to-print';
import { useDirtyTracking } from '@linm-soft-org/linm-web-common-components';
import type {
  IncidentReportSummaryItem,
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
  MonthlyIncidentReportDraft,
} from '../../../models/MedicalIncident';
import { useAppToast } from '../../../hooks/useAppToast';
import {
  medicalIncidentsAiEndpoint,
  MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE,
} from '../../../services/medicalIncidentsAi/endpoint';
import type {
  AiCreditCheckResult,
  AiCreditPack,
  AiInsufficientCreditError,
} from '../../../services/medicalIncidentsAi/types';
import { buildAnalyzeRequest } from '../../../services/medicalIncidentsAi/types';
import { applyAiMonthlyReportDraft } from '../applyAiDraft';
import { appSettings } from '../../../config/appSettings';
import {
  isMedicalReportAiEnabled,
  shouldShowMedicalReportAiButton,
} from '../../../config/medicalReportAiMode';
import { medicalIncidentEndpoint } from '../../../services/medicalIncidents/endpoint';
import {
  mergeRpnValidationErrors,
  MONTHLY_REPORT_SAVE_RULES,
  validateMonthlyReportRpnRows,
} from '../../../utils/monthlyReportValidation';
import {
  runValidation,
  scrollToFirstErrorSection,
  type ValidationErrors,
} from '../../../utils/formValidation';
import type { AiAnalysisOverride, ChartImages, RpnRow } from './PrintableRecommendationDoc';
import {
  type ChartDisplayType,
  type MonthlyReportSectionTab,
  PAGE_STYLE,
  EMPTY_RPN_ROW,
  mapDraftRpnRows,
  isNativeMobile,
  pct,
  getPeriodLabel,
  deriveMonthlySection1Stats,
} from './monthlyReportEditorShared';
import { exportMonthlyReportToDocx } from '../../../utils/monthlyReportDocxExport';
import {
  captureChartsWithRetry,
  flushPaint,
  hasAllExpectedCharts,
} from '../../../utils/chartCaptureForDocx';
import type { MonthlyReportEditorProps } from './monthlyReportEditorTypes';
import { A4_PREVIEW_WIDTH_PX } from './MonthlyReportEditorOverlays';

export function useMonthlyReportEditor({
  report,
  filters,
  activeSection: activeSectionProp,
  onSectionChange,
  onPeriodChange,
  reportCode: reportCodeProp,
  initialDraft,
  onDraftMetaChange,
  onSaveSuccess,
  onDirtyChange,
  onSubmit,
  onDelete,
  onApprove,
  onCancel,
  readOnly = false,
  permissions,
}: MonthlyReportEditorProps) {
  const toast = useAppToast();
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);
  const aiMode = appSettings.medicalReportAiMode;
  const isAiEnabled = isMedicalReportAiEnabled(aiMode);
  const showAiButton = shouldShowMedicalReportAiButton(aiMode);
  const [nativeMob] = useState(() => isNativeMobile());
  const printRef = useRef<HTMLDivElement>(null);

  const [internalSection, setInternalSection] = useState<MonthlyReportSectionTab>('summary');
  const activeSection = activeSectionProp ?? internalSection;
  const setActiveSection = useCallback((tab: MonthlyReportSectionTab) => {
    if (onSectionChange) onSectionChange(tab);
    else setInternalSection(tab);
  }, [onSectionChange]);

  const [localDateFrom, setLocalDateFrom] = useState(filters.dateFrom ?? '');
  const [localDateTo, setLocalDateTo] = useState(filters.dateTo ?? '');
  const [localIncludeDraft, setLocalIncludeDraft] = useState(filters.includeDraft ?? false);

  /** "Committed" values — only updated when user clicks Search.
   *  Effects for loading report data depend on these, not on local.*/
  const [committedDateFrom, setCommittedDateFrom] = useState(filters.dateFrom ?? '');
  const [committedDateTo, setCommittedDateTo] = useState(filters.dateTo ?? '');
  const [committedIncludeDraft, setCommittedIncludeDraft] = useState(filters.includeDraft ?? false);

  useEffect(() => {
    if (filters.dateFrom) {
      setLocalDateFrom(filters.dateFrom);
      setCommittedDateFrom(filters.dateFrom);
    }
    if (filters.dateTo) {
      setLocalDateTo(filters.dateTo);
      setCommittedDateTo(filters.dateTo);
    }
    if (filters.includeDraft !== undefined) {
      setLocalIncludeDraft(filters.includeDraft);
      setCommittedIncludeDraft(filters.includeDraft);
    }
  }, [filters.dateFrom, filters.dateTo, filters.includeDraft]);

  const effectiveDateFrom = committedDateFrom || filters.dateFrom || '';
  const effectiveDateTo = committedDateTo || filters.dateTo || '';
  const effectiveIncludeDraft = committedIncludeDraft;

  const [draftLoading, setDraftLoading] = useState(false);
  const [draftSaving, setDraftSaving] = useState(false);
  /** When creating a new report and a draft already exists for the period. */
  const [duplicateDraftDetected, setDuplicateDraftDetected] = useState(false);
  const [duplicateDraftData, setDuplicateDraftData] = useState<MonthlyIncidentReportDraft | null>(null);
  const [loadedCode, setLoadedCode] = useState('');
  const [reportNumber, setReportNumber] = useState('');
  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});

  const [summaryItems, setSummaryItems] = useState<IncidentReportSummaryItem[]>([]);
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [rpnRows, setRpnRows] = useState<RpnRow[]>(() => [EMPTY_RPN_ROW()]);
  const hasAutoPopulatedRef = useRef(false);
  /** Incremented on every Search click to force re-fetch even for existing drafts. */
  const [searchVersion, setSearchVersion] = useState(0);

  const section1 = deriveMonthlySection1Stats(report);
  const voluntaryCount = section1.voluntaryCount;
  const mandatoryCount = section1.mandatoryCount;
  const departments = section1.reportingDepartments;

  const totalTypeGroups = report.byIncidentTypeGroup.reduce((a, b) => a + b.count, 0) || 1;
  const totalOccurrence = report.byOccurrenceStatus.reduce((a, b) => a + b.count, 0) || 1;
  const totalCauseGroups = report.byCauseGroup.reduce((a, b) => a + b.count, 0) || 1;
  const activeTypeGroups = report.byIncidentTypeGroup.filter((x) => x.count > 0);
  const activeCauseGroups = report.byCauseGroup.filter((x) => x.count > 0);
  const ncGroups = report.byOccurrenceStatus.length ? report.byOccurrenceStatus : report.bySeverity;

  const [typeGroupText, setTypeGroupText] = useState(() => {
    const top = activeTypeGroups[0];
    if (!top) return '';
    return `Trong số các sự cố, sự cố liên quan đến "${top.label}" chiếm tỷ lệ cao nhất với ${pct(top.count, totalTypeGroups)}%.`;
  });

  const [occurrenceText, setOccurrenceText] = useState(() => {
    const nc0 = ncGroups.find((x) => x.key === 'not_occurred' || x.key === 'NC0');
    const nc1 = ncGroups.find((x) => x.key === 'occurred' || x.key === 'mild' || x.key === 'NC1');
    if (nc0) {
      return `Các sự cố chưa xảy ra (NC0) chiếm ${pct(nc0.count, totalOccurrence)}%${nc1 ? `, sự cố gây tổn thương nhẹ (NC1) chiếm ${pct(nc1.count, totalOccurrence)}%` : ''}.`;
    }
    return '';
  });

  const [causeGroupText, setCauseGroupText] = useState(() => {
    const top = activeCauseGroups[0];
    if (!top) return '';
    return `Nguyên nhân gây ra sự cố chủ yếu từ "${top.label}" chiếm ${pct(top.count, totalCauseGroups)}%.`;
  });

  const [typeGroupChartType, setTypeGroupChartType] = useState<ChartDisplayType>('doughnut');
  const [occurrenceChartType, setOccurrenceChartType] = useState<ChartDisplayType>('doughnut');
  const [causeGroupChartType, setCauseGroupChartType] = useState<ChartDisplayType>('doughnut');

  // ── Auto-derive default analysis text from report data ───────────────────
  // When the report loads and the analysis text is still empty (new report OR
  // existing draft saved without analysis data), derive the default text from
  // the report statistics.  Does NOT overwrite user-typed drafts.
  useEffect(() => {
    if (report.totalCount === 0) return;
    if (!typeGroupText && activeTypeGroups.length > 0) {
      const top = activeTypeGroups[0];
      if (top) {
        setTypeGroupText(`Trong số các sự cố, sự cố liên quan đến "${top.label}" chiếm tỷ lệ cao nhất với ${pct(top.count, totalTypeGroups)}%.`);
      }
    }
    if (!occurrenceText && ncGroups.length > 0) {
      const nc0 = ncGroups.find((x: { key?: string }) => x.key === 'not_occurred' || x.key === 'NC0');
      const nc1 = ncGroups.find((x: { key?: string }) => x.key === 'occurred' || x.key === 'mild' || x.key === 'NC1');
      if (nc0) {
        setOccurrenceText(`Các sự cố chưa xảy ra (NC0) chiếm ${pct(nc0.count, totalOccurrence)}%${nc1 ? `, sự cố gây tổn thương nhẹ (NC1) chiếm ${pct(nc1.count, totalOccurrence)}%` : ''}.`);
      }
    }
    if (!causeGroupText && activeCauseGroups.length > 0) {
      const top = activeCauseGroups[0];
      if (top) {
        setCauseGroupText(`Nguyên nhân gây ra sự cố chủ yếu từ "${top.label}" chiếm ${pct(top.count, totalCauseGroups)}%.`);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [report.totalCount]);
  const [chartImages, setChartImages] = useState<ChartImages>({});
  const chartImagesRef = useRef<ChartImages>({});
  chartImagesRef.current = chartImages;

  const captureTypeGroup = useCallback((b64: string) => {
    setChartImages((p) => {
      const next = { ...p, typeGroup: b64 };
      chartImagesRef.current = next;
      return next;
    });
  }, []);
  const captureOccurrence = useCallback((b64: string) => {
    setChartImages((p) => {
      const next = { ...p, occurrence: b64 };
      chartImagesRef.current = next;
      return next;
    });
  }, []);
  const captureCauseGroup = useCallback((b64: string) => {
    setChartImages((p) => {
      const next = { ...p, causeGroup: b64 };
      chartImagesRef.current = next;
      return next;
    });
  }, []);

  const [forceChartsMount, setForceChartsMount] = useState(false);

  /** Capture canvas Mục 2 → flushSync state → đợi paint (tránh first-print thiếu chart). */
  const prepareChartImagesForExport = useCallback(async (): Promise<ChartImages> => {
    const expectedKeys = (
      [
        activeTypeGroups.length > 0 ? 'typeGroup' : null,
        ncGroups.length > 0 ? 'occurrence' : null,
        activeCauseGroups.length > 0 ? 'causeGroup' : null,
      ] as const
    ).filter((k): k is 'typeGroup' | 'occurrence' | 'causeGroup' => k != null);

    // Mount Chart.js chỉ khi In/Preview/Word — không giữ chart ẩn suốt session.
    flushSync(() => {
      setForceChartsMount(true);
    });
    await flushPaint();

    const merged = await captureChartsWithRetry(chartImagesRef.current, {
      expectedKeys,
      timeoutMs: 4000,
      delayMs: 100,
      retries: 3,
    });

    chartImagesRef.current = merged;
    flushSync(() => {
      setChartImages(merged);
    });
    await flushPaint();
    await flushPaint();

    if (expectedKeys.length > 0 && !hasAllExpectedCharts(merged, expectedKeys)) {
      const again = await captureChartsWithRetry(merged, {
        expectedKeys,
        timeoutMs: 1500,
        delayMs: 150,
        retries: 2,
      });
      chartImagesRef.current = again;
      flushSync(() => {
        setChartImages(again);
      });
      await flushPaint();
      return again;
    }

    return merged;
  }, [activeTypeGroups.length, ncGroups.length, activeCauseGroups.length]);

  const [analysisOverride, setAnalysisOverride] = useState<AiAnalysisOverride>({});
  const [exportingWord, setExportingWord] = useState(false);
  const [preparingPrint, setPreparingPrint] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const previewScrollRef = useRef<HTMLDivElement>(null);
  const [zoom, setZoom] = useState(0.65);

  const [creditCheck, setCreditCheck] = useState<AiCreditCheckResult | null>(null);
  const [creditLoading, setCreditLoading] = useState(true);
  const [aiLoading, setAiLoading] = useState(false);
  const [showCreditModal, setShowCreditModal] = useState(false);
  const [suggestedPacks, setSuggestedPacks] = useState<AiCreditPack[]>([]);
  const [aiDraftApplied, setAiDraftApplied] = useState(false);

  const loadCreditCheck = useCallback(async () => {
    setCreditLoading(true);
    try {
      const check = await medicalIncidentsAiEndpoint.checkCredits(MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE);
      setCreditCheck(check);
      if (!check.canUse) setSuggestedPacks(check.suggestedPackages ?? []);
    } catch (error) {
      console.warn('[AI] credit check failed', error);
      setCreditCheck(null);
    } finally {
      setCreditLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!isAiEnabled) { setCreditLoading(false); return; }
    const t = setTimeout(() => { void loadCreditCheck(); }, 0);
    return () => clearTimeout(t);
  }, [loadCreditCheck, isAiEnabled]);

  const applyLoadedDraft = useCallback((draft: MonthlyIncidentReportDraft, markAsClean = true) => {
    if (draft.typeGroupText) setTypeGroupText(draft.typeGroupText);
    if (draft.occurrenceText) setOccurrenceText(draft.occurrenceText);
    if (draft.causeGroupText) setCauseGroupText(draft.causeGroupText);
    if (draft.typeGroupChartType) setTypeGroupChartType(draft.typeGroupChartType as ChartDisplayType);
    if (draft.occurrenceChartType) setOccurrenceChartType(draft.occurrenceChartType as ChartDisplayType);
    if (draft.causeGroupChartType) setCauseGroupChartType(draft.causeGroupChartType as ChartDisplayType);
    if (draft.rpnRows?.length) setRpnRows(mapDraftRpnRows(draft.rpnRows));
    if (draft.code) setLoadedCode(draft.code);
    setReportNumber(draft.reportNumber ?? '');
    if (draft.aiDraftApplied) setAiDraftApplied(true);
    // Only block auto-merge if the draft already has real RPN rows (not empty placeholders).
    // Empty RPN rows should still be auto-populated from report-summary data.
    const hasRealRpnData = draft.rpnRows?.some((r: { incidentName?: string | null }) => r.incidentName?.trim());
    if (hasRealRpnData) {
      hasAutoPopulatedRef.current = true;
    }
    onDraftMetaChange?.({
      code: draft.code,
      totalIncidents: draft.totalIncidents,
      aiDraftApplied: draft.aiDraftApplied,
    });
    if (markAsClean) markClean();
  }, [markClean, onDraftMetaChange]);

  useEffect(() => {
    if (!initialDraft?.id) return;
    const t = setTimeout(() => { applyLoadedDraft(initialDraft); }, 0);
    return () => clearTimeout(t);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialDraft?.id, applyLoadedDraft]);

  useEffect(() => {
    if (!effectiveDateFrom || !effectiveDateTo) return;
    let cancelled = false;
    setSummaryLoading(true);
    const t = setTimeout(async () => {
      try {
        const items = await medicalIncidentEndpoint.getReportSummary(
          effectiveDateFrom,
          effectiveDateTo,
          effectiveIncludeDraft,
        );
        if (!cancelled) setSummaryItems(items);
      } catch {
        // silent
      } finally {
        if (!cancelled) setSummaryLoading(false);
      }
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveDateFrom, effectiveDateTo, effectiveIncludeDraft, searchVersion]);

  // ── Auto-populate/merge rpnRows from summary items ──────────────────────────
  // For new reports: auto-populates when summary data first loads.
  // For existing drafts: only merges when user clicks Search (hasAutoPopulatedRef reset).
  // When merging: preserves user-entered s/o/d/causeDetail/solution, adds new incidents
  // from system, removes stale rows that are no longer in the system.
  useEffect(() => {
    if (!effectiveDateFrom || !effectiveDateTo) return;
    if (summaryLoading || summaryItems.length === 0) return;
    // Skip if draft rows are already loaded (prevents overwriting on initial load)
    if (hasAutoPopulatedRef.current) return;
    const named = summaryItems.filter((s) => s.incidentName?.trim());
    if (named.length === 0) return;

    hasAutoPopulatedRef.current = true;

    setRpnRows((prev) => {
      const existingMap = new Map<string, RpnRow>();
      for (const row of prev) {
        const key = row.incidentName.trim().toLowerCase();
        if (key) existingMap.set(key, row);
      }

      const merged = named.map((s) => {
        const key = s.incidentName!.trim().toLowerCase();
        const existing = existingMap.get(key);
        if (existing) {
          // Keep user's s/o/d, update causeDetail/solution from latest system data
          return {
            ...existing,
            causeDetail: s.causeDescription?.trim() || existing.causeDetail || '',
            solution:    s.recommendations?.trim()   || existing.solution    || '',
          };
        }
        // New incident from system — create fresh row
        const empty = EMPTY_RPN_ROW();
        return {
          ...empty,
          incidentName: s.incidentName!.trim(),
          causeDetail:  s.causeDescription?.trim() || '',
          solution:     s.recommendations?.trim() || '',
        };
      });

      return merged;
    });
  }, [summaryItems, summaryLoading, effectiveDateFrom, effectiveDateTo]);

  useEffect(() => {
    if (initialDraft?.id) return;
    if (!effectiveDateFrom || !effectiveDateTo) return;
    let cancelled = false;
    setDraftLoading(true);
    const t = setTimeout(async () => {
      try {
        const draft = await medicalIncidentEndpoint.loadMonthlyReport(effectiveDateFrom, effectiveDateTo);
        if (cancelled || !draft) return;
        // When creating a new report and a draft already exists for this period,
        // show confirm dialog instead of auto-loading the draft.
        setDuplicateDraftData(draft);
        setDuplicateDraftDetected(true);
      } catch {
        // no draft yet
      } finally {
        if (!cancelled) setDraftLoading(false);
      }
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveDateFrom, effectiveDateTo, initialDraft?.id]);

  const handleSearch = useCallback(() => {
    if (!localDateFrom || !localDateTo) {
      toast.warning('Vui lòng chọn đầy đủ Từ ngày và Đến ngày trước khi tìm.');
      return;
    }
    // Force re-fetch of summary + report data
    hasAutoPopulatedRef.current = false;
    setSearchVersion((v) => v + 1);
    setCommittedDateFrom(localDateFrom);
    setCommittedDateTo(localDateTo);
    setCommittedIncludeDraft(localIncludeDraft);
    onPeriodChange?.(localDateFrom, localDateTo, localIncludeDraft);
  }, [localDateFrom, localDateTo, localIncludeDraft, onPeriodChange, toast]);

  /**
   * Called when user confirms what to do with an existing draft for the same period:
   * - 'new': Ignore the draft, start fresh (merge from report-summary).
   * - 'use-existing': Load the draft as-is, preserving its RPN data.
   * - 'use-existing-reload': Load the draft but also re-merge fresh data from
   *   report-summary (preserves user's s/o/d scores, updates cause/solution).
   */
  const resolveDuplicateDraft = useCallback((action: 'new' | 'use-existing' | 'use-existing-reload') => {
    const draft = duplicateDraftData;
    setDuplicateDraftData(null);
    setDuplicateDraftDetected(false);
    setDraftLoading(false);

    if (action === 'new' || !draft) {
      // Ignore the existing draft — merge effect will auto-populate from summary.
      return;
    }

    // Load the existing draft's saved data
    applyLoadedDraft(draft, false);

    if (action === 'use-existing-reload') {
      // Override: force re-merge fresh report-summary data into RPN rows
      hasAutoPopulatedRef.current = false;
      setSearchVersion((v) => v + 1);
    }
  }, [applyLoadedDraft]);

  const effectiveFilters: MedicalIncidentReportFilters = {
    ...filters,
    dateFrom: effectiveDateFrom || filters.dateFrom,
    dateTo: effectiveDateTo || filters.dateTo,
    includeDraft: effectiveIncludeDraft,
  };

  const handleSaveDraft = async () => {
    if (readOnly) return;
    const saveForm = {
      dateFrom: effectiveDateFrom,
      dateTo: effectiveDateTo,
      reportNumber,
      typeGroupChartType,
      occurrenceChartType,
      causeGroupChartType,
      rpnRows: rpnRows.map((r) => ({
        incidentName: r.incidentName,
        causeDetail: r.causeDetail,
        s: r.s !== '' ? Number(r.s) : null,
        o: r.o !== '' ? Number(r.o) : null,
        d: r.d !== '' ? Number(r.d) : null,
        solution: r.solution,
      })),
    };

    let errors = runValidation(saveForm, MONTHLY_REPORT_SAVE_RULES);
    errors = mergeRpnValidationErrors(errors, validateMonthlyReportRpnRows(saveForm.rpnRows));
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      const firstMessage = errors.dateFrom ?? errors.dateTo ?? errors.reportNumber ?? errors.rpnRows
        ?? errors.typeGroupChartType ?? 'Vui lòng kiểm tra lại dữ liệu nhập';
      toast.warning(firstMessage);
      scrollToFirstErrorSection(errors, MONTHLY_REPORT_SAVE_RULES);
      if (errors.rpnRows) setActiveSection('rpn');
      return;
    }
    setValidationErrors({});

    setDraftSaving(true);
    try {
      const saved = await medicalIncidentEndpoint.saveMonthlyReport({
        dateFrom: effectiveDateFrom,
        dateTo: effectiveDateTo,
        reportNumber: reportNumber.trim() || null,
        aiDraftApplied,
        totalIncidents: report.totalCount,
        typeGroupText: typeGroupText || null,
        occurrenceText: occurrenceText || null,
        causeGroupText: causeGroupText || null,
        typeGroupChartType,
        occurrenceChartType,
        causeGroupChartType,
        rpnRows: saveForm.rpnRows,
      });
      onDraftMetaChange?.({
        code: saved.code,
        totalIncidents: saved.totalIncidents,
        aiDraftApplied: saved.aiDraftApplied,
      });
      if (saved.code) setLoadedCode(saved.code);
      setReportNumber(saved.reportNumber ?? '');
      onSaveSuccess?.(saved);
      markClean();
      toast.success('Đã lưu bản nháp báo cáo');
    } catch (err) {
      toast.fromError(err, 'Lưu bản nháp thất bại');
    } finally {
      setDraftSaving(false);
    }
  };

  const handleSubmit = async () => {
    if (!onSubmit) return;
    if (readOnly) return;
    const saveForm = {
      dateFrom: effectiveDateFrom,
      dateTo: effectiveDateTo,
      reportNumber,
      typeGroupChartType,
      occurrenceChartType,
      causeGroupChartType,
      rpnRows: rpnRows.map((r) => ({
        incidentName: r.incidentName,
        causeDetail: r.causeDetail,
        s: r.s !== '' ? Number(r.s) : null,
        o: r.o !== '' ? Number(r.o) : null,
        d: r.d !== '' ? Number(r.d) : null,
        solution: r.solution,
      })),
    };

    let errors = runValidation(saveForm, MONTHLY_REPORT_SAVE_RULES);
    errors = mergeRpnValidationErrors(errors, validateMonthlyReportRpnRows(saveForm.rpnRows));
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      const firstMessage = errors.dateFrom ?? errors.dateTo ?? errors.reportNumber ?? errors.rpnRows
        ?? errors.typeGroupChartType ?? 'Vui lòng kiểm tra lại dữ liệu nhập';
      toast.warning(firstMessage);
      scrollToFirstErrorSection(errors, MONTHLY_REPORT_SAVE_RULES);
      if (errors.rpnRows) setActiveSection('rpn');
      return;
    }

    await onSubmit({
      dateFrom: effectiveDateFrom,
      dateTo: effectiveDateTo,
      reportNumber: reportNumber.trim() || null,
      aiDraftApplied,
      totalIncidents: report.totalCount,
      typeGroupText: typeGroupText || null,
      occurrenceText: occurrenceText || null,
      causeGroupText: causeGroupText || null,
      typeGroupChartType,
      occurrenceChartType,
      causeGroupChartType,
      rpnRows: saveForm.rpnRows,
    });
  };

  const handleDelete = async () => {
    if (!onDelete || !initialDraft?.id) return;
    await onDelete(initialDraft.id);
  };

  const handleApprove = async () => {
    if (!onApprove || !initialDraft?.id) return;
    await onApprove(initialDraft.id);
  };

  const handleCancel = async () => {
    if (!onCancel || !initialDraft?.id) return;
    await onCancel(initialDraft.id);
  };

  const handleAiAnalyze = async () => {
    if (readOnly) return;
    if (creditCheck && !creditCheck.canUse) {
      setSuggestedPacks(creditCheck.suggestedPackages ?? []);
      setShowCreditModal(true);
      return;
    }
    setAiLoading(true);
    const requestId = crypto.randomUUID().replace(/-/g, '');
    try {
      const response = await medicalIncidentsAiEndpoint.analyzeReport(
        buildAnalyzeRequest(effectiveFilters),
        requestId,
      );
      const applied = applyAiMonthlyReportDraft(response.result);
      setRpnRows(applied.rpnRows);
      setAnalysisOverride(applied.analysisOverride);
      if (applied.analysisOverride.typeGroupText) setTypeGroupText(applied.analysisOverride.typeGroupText);
      if (applied.analysisOverride.occurrenceText) setOccurrenceText(applied.analysisOverride.occurrenceText);
      if (applied.analysisOverride.causeGroupText) setCauseGroupText(applied.analysisOverride.causeGroupText);
      setAiDraftApplied(true);
      markDirty();
      onDraftMetaChange?.({
        code: reportCodeProp ?? loadedCode,
        totalIncidents: report.totalCount,
        aiDraftApplied: true,
      });
      setCreditCheck((prev) =>
        prev
          ? { ...prev, balance: response.balanceRemaining, canUse: response.balanceRemaining >= prev.requiredCredits }
          : prev,
      );
      toast.success('Đã tạo bản nháp AI — vui lòng rà soát trước khi in');
      if (applied.warnings.length > 0) toast.warning(applied.warnings[0]);
    } catch (error) {
      const insufficient = error as AiInsufficientCreditError;
      if (insufficient?.status === 402) {
        setSuggestedPacks(insufficient.data?.suggestedPackages ?? []);
        setShowCreditModal(true);
        return;
      }
      toast.fromError(error, 'Phân tích AI thất bại');
    } finally {
      setAiLoading(false);
    }
  };

  const draftStatus = initialDraft?.status ?? '';
  const periodLabel = getPeriodLabel(effectiveFilters);
  const displayReportCode = reportCodeProp || loadedCode;

  const handlePrint = useReactToPrint({
    content: () => printRef.current,
    documentTitle: `BaoCao_${periodLabel.replace(/\//g, '-')}`,
    pageStyle: PAGE_STYLE,
  });

  const handleMobilePrint = () => {
    if (!printRef.current) return;
    const styleBlocks = Array.from(document.querySelectorAll('style')).map((el) => el.textContent || '').join('\n');
    const linkTags = Array.from(document.querySelectorAll('link[rel="stylesheet"]')).map((el) => el.outerHTML).join('\n');
    const newWin = window.open('', '_blank');
    if (!newWin) { handlePrint(); return; }
    newWin.document.write(`<!DOCTYPE html><html><head>
      <meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
      <title>BaoCao_${periodLabel}</title>
      ${linkTags}<style>${PAGE_STYLE}</style><style>${styleBlocks}</style>
    </head><body style="margin:0;padding:0;background:white;">
      ${printRef.current.innerHTML}
    </body></html>`);
    newWin.document.close();
    newWin.focus();
    setTimeout(() => newWin.print(), 600);
  };

  const onPrintClick = async () => {
    if (preparingPrint) return;
    setPreparingPrint(true);
    try {
      await prepareChartImagesForExport();
      if (nativeMob) handleMobilePrint();
      else handlePrint();
    } finally {
      setPreparingPrint(false);
    }
  };

  const onExportWordClick = async () => {
    if (!printRef.current) {
      toast.warning('Chưa có nội dung báo cáo để xuất Word.');
      return;
    }
    setExportingWord(true);
    try {
      const merged = await prepareChartImagesForExport();
      await exportMonthlyReportToDocx(printRef.current, {
        periodLabel,
        reportCode: displayReportCode || undefined,
        chartImages: merged,
      });
      toast.success('Đã tải file Word (.docx)');
    } catch (err) {
      toast.fromError(err, 'Xuất Word thất bại');
    } finally {
      setExportingWord(false);
    }
  };

  const openPreview = async () => {
    if (preparingPrint) return;
    setPreparingPrint(true);
    try {
      await prepareChartImagesForExport();
      setShowPreview(true);
      setTimeout(() => {
        if (previewScrollRef.current) {
          setZoom(Math.min(1, (previewScrollRef.current.clientWidth - 32) / A4_PREVIEW_WIDTH_PX));
        }
      }, 50);
    } finally {
      setPreparingPrint(false);
    }
  };

  const updateRpn = (idx: number, field: keyof RpnRow, value: string) => {
    if (readOnly) return;
    markDirty();
    setRpnRows((prev) => prev.map((r, i) => (i === idx ? { ...r, [field]: value } : r)));
  };

  const addRpnRow = () => {
    if (readOnly) return;
    markDirty();
    setRpnRows((prev) => [...prev, EMPTY_RPN_ROW()]);
  };

  const removeRpnRow = (idx: number) => {
    if (readOnly) return;
    markDirty();
    setRpnRows((prev) => (prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev));
  };

  const activeRpnCount = rpnRows.filter((r) => r.incidentName.trim()).length;

  const effectiveOverride: AiAnalysisOverride = {
    typeGroupText: typeGroupText || analysisOverride.typeGroupText,
    occurrenceText: occurrenceText || analysisOverride.occurrenceText,
    causeGroupText: causeGroupText || analysisOverride.causeGroupText,
  };

  const onReportNumberChange = (value: string) => {
    if (readOnly) return;
    setReportNumber(value);
    setValidationErrors((prev) => {
      if (!prev.reportNumber) return prev;
      const next = { ...prev };
      delete next.reportNumber;
      return next;
    });
    markDirty();
  };

  const onDateFromChange = (value: string) => {
    if (readOnly) return;
    setLocalDateFrom(value);
    setValidationErrors((prev) => {
      if (!prev.dateFrom && !prev.dateTo) return prev;
      const next = { ...prev };
      delete next.dateFrom;
      delete next.dateTo;
      return next;
    });
  };

  const onDateToChange = (value: string) => {
    setLocalDateTo(value);
    setValidationErrors((prev) => {
      if (!prev.dateFrom && !prev.dateTo) return prev;
      const next = { ...prev };
      delete next.dateFrom;
      delete next.dateTo;
      return next;
    });
  };

  const onIncludeDraftChange = (checked: boolean) => {
    if (readOnly) return;
    setLocalIncludeDraft(checked);
  };

  const onChartTypeChange = (
    setter: Dispatch<SetStateAction<ChartDisplayType>>,
    value: ChartDisplayType,
  ) => {
    if (readOnly) return;
    markDirty();
    setter(value);
  };

  const onAnalysisTextChange = (
    setter: Dispatch<SetStateAction<string>>,
    value: string,
  ) => {
    if (readOnly) return;
    markDirty();
    setter(value);
  };

  return {
    report,
    readOnly,
    nativeMob,
    printRef,
    draftStatus,
    previewScrollRef,
    activeSection,
    setActiveSection,
    draftLoading,
    draftSaving,
    reportNumber,
    onReportNumberChange,
    displayReportCode,
    periodLabel,
    localDateFrom,
    localDateTo,
    effectiveDateFrom,
    effectiveDateTo,
    localIncludeDraft,
    onDateFromChange,
    onDateToChange,
    onIncludeDraftChange,
    handleSearch,
    validationErrors,
    isAiEnabled,
    showAiButton,
    aiDraftApplied,
    creditCheck,
    creditLoading,
    aiLoading,
    showCreditModal,
    setShowCreditModal,
    suggestedPacks,
    handleSaveDraft,
    handleSubmit,
    handleDelete,
    handleApprove,
    handleCancel,
    permissions,
    handleAiAnalyze,
    onPrintClick,
    onExportWordClick,
    exportingWord,
    preparingPrint,
    forceChartsMount,
    openPreview,
    showPreview,
    setShowPreview,
    zoom,
    activeRpnCount,
    voluntaryCount,
    mandatoryCount,
    departments,
    summaryItems,
    summaryLoading,
    activeTypeGroups,
    activeCauseGroups,
    ncGroups,
    typeGroupText,
    occurrenceText,
    causeGroupText,
    setTypeGroupText,
    setOccurrenceText,
    setCauseGroupText,
    typeGroupChartType,
    occurrenceChartType,
    causeGroupChartType,
    setTypeGroupChartType,
    setOccurrenceChartType,
    setCauseGroupChartType,
    onChartTypeChange,
    onAnalysisTextChange,
    captureTypeGroup,
    captureOccurrence,
    captureCauseGroup,
    rpnRows,
    updateRpn,
    addRpnRow,
    removeRpnRow,
    effectiveFilters,
    effectiveOverride,
    chartImages,
    markDirty,
    /** Duplicate draft confirm flow */
    duplicateDraftDetected,
    duplicateDraftData,
    resolveDuplicateDraft,
  };
}

export type MonthlyReportEditorViewModel = ReturnType<typeof useMonthlyReportEditor>;
