import type { AiMonthlyReportDraft } from '../../services/medicalIncidentsAi/types';
import type { AiAnalysisOverride, RpnRow } from './components/PrintableRecommendationDoc';

export interface AppliedAiDraft {
  rpnRows:          RpnRow[];
  analysisOverride: AiAnalysisOverride;
  warnings:         string[];
}

export function applyAiMonthlyReportDraft(draft: AiMonthlyReportDraft): AppliedAiDraft {
  const rpnRows: RpnRow[] = (draft.rpnSuggestions ?? [])
    .filter((r) => r.incidentName?.trim() || r.incidentCode)
    .map((r) => ({
      incidentName: r.incidentName?.trim() || r.incidentCode || '',
      causeDetail:  r.causeDetail?.trim() || '',
      s: r.s as number | '',
      o: r.o as number | '',
      d: r.d as number | '',
      solution:     r.solution?.trim() || '',
    }));

  const analysisOverride: AiAnalysisOverride = {
    typeGroupText:  draft.analysis?.typeGroupText,
    occurrenceText: draft.analysis?.occurrenceText,
    causeGroupText: draft.analysis?.causeGroupText,
  };

  return {
    rpnRows: rpnRows.length > 0 ? rpnRows : [{ incidentName: '', causeDetail: '', s: '', o: '', d: '', solution: '' }],
    analysisOverride,
    warnings: draft.warnings ?? [],
  };
}
