/**
 * Generic HTML → DOCX export (browser).
 * SSOT: hop-dong-docx · skill /implement-export-html-to-doc · docxExportLayout.ts
 */
import { saveAs } from 'file-saver';
import {
  buildDocxPageCss,
  DOCX_BODY_STYLE,
} from './docxExportLayout';
import { applyDocxLayoutFixes } from './docxInlineStyles';
import { DOCX_TYPO, finalizeDocxTypography } from './docxTypography';
import { normalizeDocxTables } from './docxTableFix';

type HtmlDocxModule = {
  asBlob: (html: string, orientation?: string) => Blob;
};

const CHART_IMG_STYLE =
  'max-width:480px;width:auto;max-height:300px;height:auto;display:block;margin:8px auto 4px';

function getHtmlDocx(): HtmlDocxModule {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  return require('html-docx-js/dist/html-docx') as HtmlDocxModule;
}

export function buildWordExportHtml(
  bodyHtml: string,
  docCss: string,
  bodyStyle = DOCX_BODY_STYLE,
): string {
  const pageCss = buildDocxPageCss();
  return (
    '<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><style>' +
    pageCss +
    '\n' +
    docCss +
    '</style></head><body style="' +
    bodyStyle +
    '">' +
    bodyHtml +
    '</body></html>'
  );
}

export async function assertValidDocxBlob(blob: Blob): Promise<Blob> {
  const ab = await blob.arrayBuffer();
  const u8 = new Uint8Array(ab);
  if (u8.length < 4 || u8[0] !== 0x50 || u8[1] !== 0x4b) {
    throw new Error('File tải về không hợp lệ (không phải DOCX).');
  }
  return blob;
}

/** Gắn ảnh biểu đồ base64 vào clone — resize xuống max 480×300 + giữ legend + caption bên dưới. */
export function patchChartImagesInClone(
  clone: HTMLElement,
  chartImages: Record<string, string | undefined>,
): void {
  clone.querySelectorAll('[data-lin-docx-chart]').forEach((slot) => {
    const key = slot.getAttribute('data-lin-docx-chart');
    if (!key) return;
    const src = chartImages[key];
    if (!src) return;

    const captionEl = slot.querySelector('[data-lin-docx-chart-caption]');
    const captionHtml = captionEl
      ? `<div data-lin-docx-chart-caption="" data-lin-docx-typo="caption10Italic" style="${DOCX_TYPO.caption10Italic}">${captionEl.innerHTML}</div>`
      : '';

    // Preserve legend (color chips) — <font color>■</font> + nbsp spacing
    // Word MHT supports <font color> natively, ■ renders as colored square
    const legendEl = slot.querySelector('[data-lin-docx-legend]');
    let legendHtml = '';
    if (legendEl) {
      const itemEls = Array.from(legendEl.querySelectorAll('[data-lin-docx-legend-item]'));
      const parts: string[] = [];
      for (const item of itemEls) {
        const chip = item.querySelector('[data-lin-docx-legend-chip]');
        const label = item.querySelector('[data-lin-docx-legend-label]');
        const value = item.querySelector('[data-lin-docx-legend-value]');
        const color = chip?.getAttribute('data-color') || '#888';
        // Chip group: ■ Label 12 (34%)
        parts.push(
          `<span style="white-space:nowrap">` +
          `<font color="${color}">■</font>` +
          `<b>&nbsp;` + (label?.textContent || '') + `&nbsp;</b>` +
          '<span style="color:#444;font-size:12px">' + (value?.textContent || '') + '</span>' +
          `</span>`,
        );
      }
      legendHtml = `<div style="text-align:center;margin:6px auto 2px;max-width:480px;font-size:13px;line-height:1.8">${parts.join('&nbsp;&nbsp;&nbsp;')}</div>`;
    }

    // Word MHT import: <p align="center"> + width attribute là đáng tin cậy nhất
    // width=300 → Word sets extent ~300px, height giữ aspect ratio
    slot.innerHTML =
      `<p align="center">` +
      `<img src="${src}" alt="" width="300" height="300" />` +
      `</p>` +
      legendHtml +
      captionHtml;
  });
}

export function prepareDocxExportClone(
  sourceRoot: HTMLElement,
  options?: { chartImages?: Record<string, string | undefined> },
): HTMLElement {
  const clone = sourceRoot.cloneNode(true) as HTMLElement;
  clone.querySelectorAll('script, style, button').forEach((node) => node.remove());
  clone.querySelectorAll('a[href]').forEach((anchor) => {
    const span = document.createElement('span');
    span.textContent = anchor.textContent || '';
    anchor.replaceWith(span);
  });

  applyDocxLayoutFixes(sourceRoot, clone);

  if (options?.chartImages) {
    patchChartImagesInClone(clone, options.chartImages);
    finalizeDocxTypography(clone);
    normalizeDocxTables(clone);
  }

  clone.querySelectorAll('[data-lin-docx-export] img, [data-lin-docx-chart] img').forEach((img) => {
    if (!(img instanceof HTMLImageElement)) return;
    if (!img.getAttribute('style')) {
      img.setAttribute('style', CHART_IMG_STYLE);
    }
  });

  return clone;
}

export function sanitizeExportBodyHtml(
  sourceRoot: HTMLElement,
  options?: { chartImages?: Record<string, string | undefined> },
): string {
  const clone = prepareDocxExportClone(sourceRoot, options);
  return clone.innerHTML;
}

export async function downloadHtmlAsDocx(options: {
  bodyHtml: string;
  docCss: string;
  fileName: string;
  bodyStyle?: string;
}): Promise<void> {
  const htmlDocx = getHtmlDocx();
  const fullHtml = buildWordExportHtml(options.bodyHtml, options.docCss, options.bodyStyle);
  const blob = htmlDocx.asBlob(fullHtml);
  const valid = await assertValidDocxBlob(blob);
  const name = options.fileName.endsWith('.docx') ? options.fileName : `${options.fileName}.docx`;
  saveAs(valid, name);
}

export async function downloadElementAsDocx(
  root: HTMLElement,
  options: {
    docCss: string;
    fileName: string;
    bodyStyle?: string;
    chartImages?: Record<string, string | undefined>;
  },
): Promise<void> {
  const bodyHtml = sanitizeExportBodyHtml(root, { chartImages: options.chartImages });
  if (!bodyHtml.trim()) {
    throw new Error('Chưa có nội dung để xuất Word.');
  }
  await downloadHtmlAsDocx({ bodyHtml, ...options });
}

export function buildSafeDocxFileName(prefix: string, parts: string[]): string {
  const safe = parts
    .map((p) => (p || '').trim().replace(/[^\w.-]+/g, '_').replace(/_+/g, '_'))
    .filter(Boolean)
    .join('_');
  return `${prefix}${safe ? `_${safe}` : ''}.docx`;
}
