/**
 * Typography SSOT — parity PrintableRecommendationDoc.module.css · In A4.
 * html-docx-js: bắt buộc inline pt + Times New Roman (cấm px từ getComputedStyle).
 */

export const DOCX_FONT = "font-family:'Times New Roman',Times,serif";

/** Map role → inline style (pt) — mirror print CSS module */
export const DOCX_TYPO: Record<string, string> = {
  root: `${DOCX_FONT};font-size:12pt;line-height:1.45;color:#000`,
  header10: `${DOCX_FONT};font-size:10pt;line-height:1.5`,
  header10Bold: `${DOCX_FONT};font-size:10pt;line-height:1.5;font-weight:bold`,
  header10Underline: `${DOCX_FONT};font-size:10pt;line-height:1.5;text-decoration:underline`,
  header10Italic: `${DOCX_FONT};font-size:10pt;line-height:1.5;font-style:italic`,
  title14: `${DOCX_FONT};font-size:14pt;font-weight:bold;text-transform:uppercase;line-height:1.3;text-align:center`,
  subtitle12: `${DOCX_FONT};font-size:12pt;font-weight:bold;text-transform:uppercase;line-height:1.4;text-align:center`,
  section12Bold: `${DOCX_FONT};font-size:12pt;font-weight:bold`,
  body11: `${DOCX_FONT};font-size:11pt;line-height:1.6`,
  body11Indent: `${DOCX_FONT};font-size:11pt;line-height:1.7`,
  bullet11Bold: `${DOCX_FONT};font-size:11pt;font-weight:bold`,
  analysis11Italic: `${DOCX_FONT};font-size:11pt;line-height:1.7;font-style:italic`,
  noData11Italic: `${DOCX_FONT};font-size:11pt;font-style:italic;color:#555`,
  table11: `${DOCX_FONT};font-size:11pt`,
  tableCell11: `${DOCX_FONT};font-size:11pt;vertical-align:top`,
  tableHead11: `${DOCX_FONT};font-size:11pt;font-weight:bold;text-align:center;vertical-align:top`,
  caption10Italic: `${DOCX_FONT};font-size:10pt;font-style:italic;text-align:center;color:#333;margin-top:4px`,
  sigTitle11: `${DOCX_FONT};font-size:11pt;font-weight:bold;text-transform:uppercase;text-align:center`,
  sigHint10: `${DOCX_FONT};font-size:10pt;font-style:italic;text-align:center;margin-top:2px`,
  sigName11: `${DOCX_FONT};font-size:11pt;font-weight:bold;text-align:center;margin-top:48px;min-height:16px`,
  pct11: `${DOCX_FONT};font-size:11pt`,
  causeDetail105: `${DOCX_FONT};font-size:10.5pt;line-height:1.5`,
  solution11: `${DOCX_FONT};font-size:11pt;line-height:1.5`,
  solutionEmpty11: `${DOCX_FONT};font-size:11pt;font-style:italic;color:#666`,
};

export function pxFontSizeToPt(fontSize: string): string {
  if (!fontSize) return '12pt';
  if (fontSize.endsWith('pt')) return fontSize;
  if (fontSize.endsWith('px')) {
    const px = parseFloat(fontSize);
    if (!Number.isNaN(px)) {
      const pt = px * 0.75;
      return `${Math.round(pt * 100) / 100}pt`;
    }
  }
  return fontSize;
}

const PRESERVE_PROPS = ['text-align', 'vertical-align', 'font-weight', 'font-style', 'color', 'text-decoration'];

function extractPreservedStyles(existing: string): string {
  const parts: string[] = [];
  for (const prop of PRESERVE_PROPS) {
    const re = new RegExp(`${prop}\\s*:\\s*[^;]+`, 'i');
    const m = existing.match(re);
    if (m) parts.push(m[0].trim());
  }
  return parts.join(';');
}

/** Áp SSOT role lên clone — giữ text-align / vertical-align từ bước inline trước. */
export function applyTypographyRoles(root: HTMLElement): void {
  root.querySelectorAll('[data-lin-docx-typo]').forEach((node) => {
    if (!(node instanceof HTMLElement)) return;
    const role = node.getAttribute('data-lin-docx-typo') || '';
    const base = DOCX_TYPO[role];
    if (!base) return;
    const preserved = extractPreservedStyles(node.getAttribute('style') || '');
    node.setAttribute('style', preserved ? `${base};${preserved}` : base);
  });
}

/** Mọi phần tử không có role — ép Times New Roman; chuẩn hóa font-size px → pt. */
export function enforceDocxFontTree(root: HTMLElement): void {
  root.querySelectorAll('*').forEach((node) => {
    if (!(node instanceof HTMLElement)) return;
    if (node.hasAttribute('data-lin-docx-typo')) return;

    let prev = node.getAttribute('style') || '';
    if (!/font-family/i.test(prev)) {
      prev = prev ? `${DOCX_FONT};${prev}` : DOCX_FONT;
    }
    const fsMatch = prev.match(/font-size\s*:\s*([^;]+)/i);
    if (fsMatch && /px/i.test(fsMatch[1])) {
      const pt = pxFontSizeToPt(fsMatch[1].trim());
      prev = prev.replace(/font-size\s*:\s*[^;]+/i, `font-size:${pt}`);
    }
    if (prev) node.setAttribute('style', prev);
  });
}

export function finalizeDocxTypography(clone: HTMLElement): void {
  applyTypographyRoles(clone);
  enforceDocxFontTree(clone);
}
