import type { MedicalIncidentReportFilters } from '../../models/MedicalIncident';

export interface AiCreditPack {
  packId: string;
  credits: number;
  priceVnd: number;
  label: string;
  recurring?: boolean;
  recommended?: boolean;
}

export interface AiCreditCheckResult {
  featureKey: string;
  balance: number;
  requiredCredits: number;
  canUse: boolean;
  userPackage?: string;
  defaultGrant: number;
  suggestedPackages: AiCreditPack[];
}

export interface AiGenerateAnalyzeRequest {
  year?: number;
  dateFrom?: string;
  dateTo?: string;
  reportingDepartmentId?: string;
  includeDraft?: boolean;
  scopes?: string[];
}

export interface AiAnalysisResult {
  typeGroupText?: string;
  occurrenceText?: string;
  causeGroupText?: string;
}

export interface AiRecommendationItem {
  groupKey: string;
  solution: string;
  priority?: 'high' | 'medium' | 'low';
}

export interface AiRpnSuggestion {
  incidentCode?: string;
  incidentName?: string;
  s: number;
  o: number;
  d: number;
  rpn?: number;
  rationale?: string;
  causeDetail?: string;
  solution?: string;
}

export interface AiMonthlyReportDraft {
  analysis?: AiAnalysisResult;
  recommendations?: AiRecommendationItem[];
  rpnSuggestions?: AiRpnSuggestion[];
  warnings?: string[];
}

export interface AiGenerateAnalyzeResponse {
  result: AiMonthlyReportDraft;
  creditsSpent: number;
  balanceRemaining: number;
  requiresReview: boolean;
  warnings?: string[];
  model?: string;
  promptVersion?: string;
}

export interface AiInsufficientCreditData {
  errorCode?: string;
  featureKey?: string;
  requiredCredits?: number;
  balance?: number;
  suggestedPackages?: AiCreditPack[];
  upgradeUrl?: string;
}

export interface AiInsufficientCreditError {
  status: 402;
  message: string;
  data?: AiInsufficientCreditData;
}

export function buildAnalyzeRequest(
  filters: MedicalIncidentReportFilters,
): AiGenerateAnalyzeRequest {
  return {
    year: filters.year,
    dateFrom: filters.dateFrom,
    dateTo: filters.dateTo,
    reportingDepartmentId: filters.reportingDepartmentId || undefined,
    includeDraft: filters.includeDraft ?? false,
    scopes: ['analysis', 'recommendations', 'rpn'],
  };
}
